GO
USE AssetsDB;
GO
SET NOCOUNT ON;
DECLARE @img TABLE (Kind NVARCHAR(30) PRIMARY KEY, Data VARBINARY(MAX));
INSERT @img (Kind, Data) VALUES
 (N'desktop', ),
 (N'laptop', ),
 (N'printer', ),
 (N'printer_color', ),
 (N'scanner', ),
 (N'desk', ),
 (N'meeting', ),
 (N'chair', ),
 (N'chair_old', ),
 (N'cabinet', ),
 (N'projector', ),
 (N'screen', ),
 (N'aircon', ),
 (N'copier', ),
 (N'press', ),
 (N'scale', ),
 (N'station', );

-- ربط كل أصل بصورة نوعه
UPDATE a SET a.Image = i.Data
FROM dbo.Asset a
JOIN (VALUES
 (N'PC-001', N'desktop'),
 (N'PC-002', N'desktop'),
 (N'PC-003', N'desktop'),
 (N'PC-004', N'desktop'),
 (N'PC-008', N'desktop'),
 (N'PC-005', N'laptop'),
 (N'PC-006', N'laptop'),
 (N'PC-007', N'laptop'),
 (N'PR-001', N'printer'),
 (N'PR-002', N'printer_color'),
 (N'PR-003', N'scanner'),
 (N'FN-001', N'desk'),
 (N'FN-004', N'meeting'),
 (N'FN-002', N'chair'),
 (N'FN-005', N'chair_old'),
 (N'FN-003', N'cabinet'),
 (N'EL-001', N'projector'),
 (N'EL-002', N'screen'),
 (N'EL-003', N'aircon'),
 (N'EL-004', N'copier'),
 (N'EQ-001', N'press'),
 (N'EQ-002', N'scale'),
 (N'EQ-003', N'station')
) AS x(SerialNo, Kind) ON x.SerialNo = a.SerialNo
JOIN @img i ON i.Kind = x.Kind;

PRINT CONCAT(N'تمت إضافة الصور إلى ', @@ROWCOUNT, N' أصلاً.');
GO